async () => {
  // Find the iframe containing the challenge
  const iframes = document.querySelectorAll('iframe');
  let result = {iframeCount: iframes.length};
  for (let i = 0; i < iframes.length; i++) {
    result['iframe_' + i + '_src'] = iframes[i].src;
    try {
      const doc = iframes[i].contentDocument;
      if (doc) {
        const cb = doc.querySelector('input[type="checkbox"]');
        result['iframe_' + i + '_has_checkbox'] = !!cb;
        if (cb) {
          cb.click();
          result['iframe_' + i + '_clicked'] = true;
        }
      }
    } catch (e) {
      result['iframe_' + i + '_error'] = e.message;
    }
  }
  return result;
}

async () => {
  const iframes = document.querySelectorAll('iframe');
  const result = {iframeCount: iframes.length, iframes: []};
  for (let i = 0; i < iframes.length; i++) {
    const iframe = iframes[i];
    const info = {src: iframe.src, id: iframe.id, name: iframe.name};
    try {
      const doc = iframe.contentDocument;
      if (doc) {
        const cb = doc.querySelector('input[type="checkbox"]');
        info.hasCheckbox = !!cb;
        if (cb) {
          cb.click();
          info.clicked = true;
        }
        // Also try to get body text
        info.bodyText = doc.body ? doc.body.innerText.substring(0, 500) : '';
      } else {
        info.hasDoc = false;
      }
    } catch (e) {
      info.error = e.message;
    }
    result.iframes.push(info);
  }
  return result;
}

async () => {
  return JSON.stringify({
    iframeCount: document.querySelectorAll('iframe').length,
    title: document.title,
    url: window.location.href
  });
}

async () => {
  const iframes = document.querySelectorAll('iframe');
  const result = {iframeCount: iframes.length};
  for (let i = 0; i < iframes.length; i++) {
    const iframe = iframes[i];
    result['iframe_' + i] = {src: iframe.src};
    try {
      const doc = iframe.contentDocument;
      if (doc) {
        const cb = doc.querySelector('input[type="checkbox"]');
        result['iframe_' + i].hasDoc = true;
        if (cb) {
          result['iframe_' + i].hasCheckbox = true;
          result['iframe_' + i].checked = cb.checked;
          cb.click();
          result['iframe_' + i].afterClick = cb.checked;
        }
      } else {
        result['iframe_' + i].hasDoc = false;
      }
    } catch (e) {
      result['iframe_' + i].error = e.message;
    }
  }
  return JSON.stringify(result);
}
